std::string digest(const J&j){const auto s=j.dump();return eventio::sha256(std::vector<std::uint8_t>(s.begin(),s.end()));}
std::size_t scalar_bytes(const std::string&s){if(s=="<f8"||s=="f64"||s=="float64"||s=="<i8"||s=="i64"||s=="int64")return 8;if(s=="<u4"||s=="u32"||s=="uint32"||s=="<i4"||s=="i32"||s=="int32")return 4;if(s=="<u2"||s=="u16"||s=="uint16")return 2;if(s=="|u1"||s=="u8"||s=="uint8"||s=="|i1"||s=="i8"||s=="int8")return 1;throw std::runtime_error("unsupported source dtype "+s);}
