using Key=std::tuple<std::string,std::string,std::string,std::int64_t>;
Key key(const JointObservation&r){return{r.source_dataset_id,r.source_row_id,r.shot_id,r.pts};}
std::vector<double> append_only_remap_unused(const std::vector<std::string>&ids,const std::vector<double>&values,const std::vector<std::string>&newids,std::size_t&added){need(ids.size()==values.size(),"old multiplier schema mismatch");std::unordered_map<std::string_view,std::size_t>index;index.reserve(ids.size());for(std::size_t i=0;i<ids.size();++i)need(index.emplace(ids[i],i).second,"duplicate old constraint ID");std::vector<unsigned char>seen(ids.size());std::vector<double>out;out.reserve(newids.size());added=0;for(const auto&id:newids){auto p=index.find(id);if(p==index.end()){out.push_back(0.);++added;}else{need(!seen[p->second],"duplicate new constraint ID");seen[p->second]=1;out.push_back(values[p->second]);}}need(std::find(seen.begin(),seen.end(),0)==seen.end(),"scope append removed an old physical constraint");return out;}

